203	  async handleLine(line: string): Promise<void> {
204	    if (!line.trim()) return;
205	    let command: SidecarCommand;
206	    try {
207	      command = parseCommand(line);
208	    } catch (err) {
209	      const id = err instanceof ProtocolError ? err.id : undefined;
210	      this.emit({ type: "error", ...(id ? { id } : {}), code: "BAD_REQUEST", message: (err as Error).message });
211	      return;
212	    }
213	    if (this.unsupportedProtocol && command.type !== "initialize" && command.type !== "shutdown") {
214	      this.emit({
215	        type: "error",
216	        id: "id" in command ? command.id : undefined,
217	        code: "UNSUPPORTED_PROTOCOL",
218	        message: this.unsupportedProtocol,
219	      });
220	      return;
221	    }
222	    switch (command.type) {
223	      case "initialize":
224	        this.initialize(command.id, command.protocol_min ?? PROTOCOL_VERSION, command.protocol_max ?? PROTOCOL_VERSION, command.experimental === true);
225	        return;
226	      case "prompt.submit":
227	        this.submit(command.id, command.text);
228	        return;
229	      case "steer":
230	        this.steer(command.id, command.text);
231	        return;
232	      case "cancel":
233	        this.cancel();
234	        return;
235	      case "approve":
236	        this.resolveApproval(command.id, true, command.always);
237	        return;
238	      case "deny":
239	        this.resolveApproval(command.id, false, false);
240	        return;
241	      case "answer":
242	        // Bound to the decision by id; consumed when a turn reaches it (an unresolved steering conflict: at the next
243	        // turn's start). An id no turn asked about is simply never consumed.
244	        this.app.getAgent().setOperatorAnswers(new Map([[command.question, command.option]]));
245	        this.emit({ type: "notice", text: `Answer recorded for question ${command.question}: ${command.option}. It applies when the next turn reaches that decision.` });
246	        return;
247	      case "checkpoint.choice":
248	        this.resolveCheckpointChoice(command.id, command.choice);
249	        return;
250	      case "slash":
251	        this.slash(command.id, command.command, command.args);
252	        return;
253	      case "tool.detail":
254	      case "receipt":
255	        try {
256	          if (command.type === "tool.detail") this.toolDetail(command.id, command.evidence);
257	          else this.emit({ type: "receipt", id: command.id, sections: this.receipt() });
258	        } catch (err) {
259	          const message = errorText(err);
260	          this.emit({ type: "error", id: command.id, code: "INTERNAL", message });
261	        }
262	        return;
263	      case "models.list":
264	        if (this.app.getAgent().getApprovalMode() === "read-only") {
265	          this.emit({ type: "error", id: command.id, code: "BUSY", message: "Provider discovery is disabled while the session is in read-only mode." });
266	          return;
267	        }
268	        void this.modelsList(command.id);
269	        return;
270	      case "model.select":
271	        if (this.app.getAgent().getApprovalMode() === "read-only") {
272	          this.emit({ type: "error", id: command.id, code: "BUSY", message: "Model changes are disabled while the session is in read-only mode." });
273	          return;
274	        }
275	        this.modelSelect(command.id, command.provider, command.model);
276	        return;
277	      case "provider.connect":
278	        if (this.app.getAgent().getApprovalMode() === "read-only") {
279	          this.emit({ type: "provider.result", id: command.id, provider: command.provider, success: false, message: "Provider connections are disabled while the session is in read-only mode." });
