867	  private openApproval(turnId: string, signal: AbortSignal, tool: string, args: Record<string, any>): Promise<boolean> {
868	    if (tool !== DELIBERATE_APPROVAL) this.operatorDeclined = false;
869	    if (this.alwaysApprove && tool !== DELIBERATE_APPROVAL) return Promise.resolve(true);
870	    if (signal.aborted) return Promise.resolve(false);
871	    const id = `approval-${++this.approvalSeq}`;
872	    return new Promise<boolean>((resolve) => {
873	      const onAbort = () => settle(false);
874	      const settle = (approved: boolean) => {
875	        signal.removeEventListener("abort", onAbort);
876	        this.pendingApproval = undefined;
877	        resolve(approved);
878	      };
879	      signal.addEventListener("abort", onAbort, { once: true });
880	      this.pendingApproval = { id, tool, settle };
881	      this.emit({
882	        type: "approval.request",
883	        id,
884	        turn_id: turnId,
885	        tool,
886	        subject: toolSubject(args, tool),
887	        preview: redactedJson(args),
888	        review: approvalReview(tool, args, this.app.getConfig().workspace),
889	      });
890	    });
891	  }
