893	  private resolveApproval(id: string, approved: boolean, always: boolean): void {
894	    const pending = this.pendingApproval;
895	    if (!pending || pending.id !== id) {
896	      this.emit({ type: "error", id, code: "NO_PENDING_APPROVAL", message: `No pending approval with id ${id}.` });
897	      return;
898	    }
899	    if (approved && always && pending.tool !== DELIBERATE_APPROVAL) {
900	      this.alwaysApprove = true;
901	      this.mode = "auto";
902	      this.app.getAgent().setApprovalMode("auto");
