export interface RunTaskOptions {
  json?: boolean;
  quiet?: boolean;
  onConfirm?: (tool: string, args: any) => Promise<boolean>;
  resumeTaskId?: string;
  /** Answers to the questions a blocked headless run asked (VC-9), keyed by `needsInput.id`. */
  answers?: ReadonlyMap<string, NeedsInputOption>;
  /** Free-text replies to questions that are not a yes/no (a blocked requirement), keyed by `needsInput.id`. */
  replies?: ReadonlyMap<string, string>;
  /** Operator cancellation authority for this task. */
  signal?: AbortSignal;
  /** Execute one model/tool cycle and pause deterministically (WP-1106). */
  step?: boolean;
  /** Live events of this task (assistant text, tool start/end, notices); detached when the task ends. */
  observer?: AgentObserver;
}

export interface TaskExecutionResult {
  taskId: string;
  success: boolean;
  status: TaskLifecycleStatus;
  prompt: string;
  output: string;
  plan: DurablePlanPhase[];
