  .command("acp")
  .description("Serve the Agent Client Protocol over stdio")
  .action(() => {
    const config = buildConfig(program.opts());
    // D-AC-3: an ACP client is untrusted, and under auto approval no tool call would ask it or anyone else. Whatever
